import { detectDeviceTier } from "./device-tier";
import { SURFACE_STORAGE_KEY, type SurfaceMode } from "./types";

/**
 * External store for the four appearance inputs.
 *
 * These genuinely live outside React — media queries, localStorage, and a
 * one-time device probe — so they are read with useSyncExternalStore rather
 * than mirrored into state inside an effect. That also gets first paint
 * right: `getServerSnapshot` matches what the pre-hydration script applied.
 */

export interface SurfaceSnapshot {
  competitionMode: boolean;
  reducedTransparency: boolean;
  reducedMotion: boolean;
  lowTier: boolean;
}

const SERVER_SNAPSHOT: SurfaceSnapshot = {
  competitionMode: false,
  reducedTransparency: false,
  reducedMotion: false,
  lowTier: false,
};

let snapshot: SurfaceSnapshot = SERVER_SNAPSHOT;
let initialized = false;
const listeners = new Set<() => void>();

let mqTransparency: MediaQueryList | null = null;
let mqMotion: MediaQueryList | null = null;

function read(): SurfaceSnapshot {
  let competitionMode = false;
  try {
    competitionMode = localStorage.getItem(SURFACE_STORAGE_KEY) === "1";
  } catch {
    // Private mode / storage disabled — the toggle just won't persist.
  }
  return {
    competitionMode,
    reducedTransparency: mqTransparency?.matches ?? false,
    reducedMotion: mqMotion?.matches ?? false,
    lowTier: detectDeviceTier() === "low",
  };
}

/** Replaces the snapshot only when a field actually changed, so identity is
 *  stable and useSyncExternalStore doesn't loop. */
function refresh() {
  const next = read();
  const changed = (Object.keys(next) as Array<keyof SurfaceSnapshot>).some(
    (k) => next[k] !== snapshot[k],
  );
  if (changed) {
    snapshot = next;
    listeners.forEach((l) => l());
  }
}

export function subscribeSurface(listener: () => void): () => void {
  if (!initialized && typeof window !== "undefined") {
    initialized = true;
    mqTransparency = window.matchMedia("(prefers-reduced-transparency: reduce)");
    mqMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    mqTransparency.addEventListener("change", refresh);
    mqMotion.addEventListener("change", refresh);
    // Competition mode toggled in another tab.
    window.addEventListener("storage", refresh);
    snapshot = read();
  }
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

export function getSurfaceSnapshot(): SurfaceSnapshot {
  return snapshot;
}

export function getServerSurfaceSnapshot(): SurfaceSnapshot {
  return SERVER_SNAPSHOT;
}

export function setCompetitionMode(on: boolean) {
  try {
    localStorage.setItem(SURFACE_STORAGE_KEY, on ? "1" : "0");
  } catch {
    // Non-fatal; fall through so the toggle still applies this session.
  }
  // localStorage writes don't fire `storage` in the originating tab.
  snapshot = { ...snapshot, competitionMode: on };
  listeners.forEach((l) => l());
}

/**
 * Collapses the four inputs into one SurfaceMode.
 *
 * Competition mode is an explicit choice made at an event, so it wins over
 * every automatic signal.
 */
export function resolveMode(s: SurfaceSnapshot): SurfaceMode {
  if (s.competitionMode) return "contrast";
  if (s.reducedTransparency || s.lowTier) return "solid";
  return "glass";
}
