import type { DeviceTier } from "./types";

/**
 * Our users are on school Chromebooks and budget Androids, in a gym, on
 * battery, all day. `backdrop-filter` is GPU-expensive and those are exactly
 * the devices that handle it worst.
 *
 * There is no reliable "how fast is this GPU" API, so this is a deliberately
 * conservative heuristic: anything that looks constrained gets the solid
 * treatment. A high-end device misclassified as low loses some polish; a low
 * -end device misclassified as high drops frames all day at a competition.
 * We bias hard toward the first mistake.
 */
export function detectDeviceTier(): DeviceTier {
  if (typeof window === "undefined") return "high";

  // No backdrop-filter support at all — solid is the only correct answer.
  if (
    typeof CSS !== "undefined" &&
    CSS.supports &&
    !CSS.supports("backdrop-filter", "blur(1px)") &&
    !CSS.supports("-webkit-backdrop-filter", "blur(1px)")
  ) {
    return "low";
  }

  const nav = navigator as Navigator & {
    deviceMemory?: number;
    connection?: { saveData?: boolean };
  };

  // Data Saver is a strong signal the user is on a constrained device and
  // wants us to do less work.
  if (nav.connection?.saveData) return "low";

  // deviceMemory is Chromium-only and bucketed (0.25/0.5/1/2/4/8).
  // <= 4GB covers most school Chromebooks and budget Androids.
  if (typeof nav.deviceMemory === "number" && nav.deviceMemory <= 4) {
    return "low";
  }

  if (
    typeof nav.hardwareConcurrency === "number" &&
    nav.hardwareConcurrency <= 4
  ) {
    return "low";
  }

  return "high";
}

/**
 * How many blurred layers may be composited at once. Exceeding this is the
 * fastest way to tank frame rate on the devices we care about.
 *
 * Enforced by the GlassSurface primitive, which falls back to a solid fill
 * once the budget is spent. In practice the budget is: nav bar, tab bar, and
 * one floating action or sheet. Never blur behind a long scrolling list.
 */
export const MAX_BLURRED_LAYERS = 3;
