"use client";

import { useEffect, useMemo, useSyncExternalStore } from "react";
import {
  getServerSurfaceSnapshot,
  getSurfaceSnapshot,
  resolveMode,
  setCompetitionMode,
  subscribeSurface,
} from "./surface-store";
import { SURFACE_STORAGE_KEY, type SurfaceState } from "./types";
import { createContext, useContext } from "react";

const SurfaceContext = createContext<SurfaceState | null>(null);

export function SurfaceProvider({ children }: { children: React.ReactNode }) {
  const snapshot = useSyncExternalStore(
    subscribeSurface,
    getSurfaceSnapshot,
    getServerSurfaceSnapshot,
  );

  const mode = resolveMode(snapshot);

  // Contrast mode also suppresses motion — a loud gym on a dying battery is
  // not where we spend frames on spring physics.
  const reducedMotion = snapshot.reducedMotion || mode === "contrast";

  // Writing to <html> is exactly the "update an external system" case
  // effects are for.
  useEffect(() => {
    const root = document.documentElement;
    root.dataset.surfaceMode = mode;
    root.dataset.reducedMotion = String(reducedMotion);
  }, [mode, reducedMotion]);

  const value = useMemo<SurfaceState>(
    () => ({
      mode,
      reducedMotion,
      competitionMode: snapshot.competitionMode,
      setCompetitionMode,
    }),
    [mode, reducedMotion, snapshot.competitionMode],
  );

  return (
    <SurfaceContext.Provider value={value}>{children}</SurfaceContext.Provider>
  );
}

export function useSurface(): SurfaceState {
  const ctx = useContext(SurfaceContext);
  if (!ctx) throw new Error("useSurface must be used within <SurfaceProvider>");
  return ctx;
}

/**
 * Runs before hydration so a user who enabled competition mode doesn't get a
 * flash of glass first.
 *
 * Device tier is deliberately NOT computed here — a brief flash of glass on a
 * low-tier device is a much smaller problem than blocking first paint on that
 * same device.
 */
export const surfaceBootstrapScript = `
(function(){try{
  var c = localStorage.getItem(${JSON.stringify(SURFACE_STORAGE_KEY)}) === "1";
  var rt = matchMedia("(prefers-reduced-transparency: reduce)").matches;
  var rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  var m = c ? "contrast" : (rt ? "solid" : "glass");
  document.documentElement.dataset.surfaceMode = m;
  document.documentElement.dataset.reducedMotion = String(rm || m === "contrast");
}catch(e){document.documentElement.dataset.surfaceMode="glass";}})();
`;
