/**
 * The ONE resolved appearance token.
 *
 * Four independent inputs (device capability, prefers-reduced-transparency,
 * the competition-mode toggle, and backdrop-filter support) would produce 16
 * combinations of every glass surface. That does not survive contact with a
 * real codebase — half of it goes untested and the rest drifts.
 *
 * So they collapse here, once, into three values. Components read CSS
 * variables keyed off `data-surface-mode` and never inspect the inputs.
 */
export type SurfaceMode = "glass" | "solid" | "contrast";

/** Device capability tier, used only as an input to SurfaceMode. */
export type DeviceTier = "high" | "low";

export interface SurfaceState {
  mode: SurfaceMode;
  /** Motion is a separate single boolean, not a fourth surface variant. */
  reducedMotion: boolean;
  /** Whether the user has competition mode switched on. */
  competitionMode: boolean;
  setCompetitionMode: (on: boolean) => void;
}

export const SURFACE_STORAGE_KEY = "ftc:competition-mode";
